"use strict";

const sdk = require("stripe");

async function createRecurringCharge(customerId) {
  const result = await sdk.charges.create({
    customer: customerId,
    amount: 2_500,
    currency: "usd",
    description: "Controlled Depfix Stripe seed",
  });
  return result.value;
}

module.exports = { createRecurringCharge };

